Name: buffer_new_with_size
Signature: buffer_t* buffer_new_with_size(size_t n)
Description: /**
 * @brief Allocate a new buffer with a specified initial size.
 *
 * Creates a buffer_t structure and allocates a zero-initialized data region
 * of n+1 bytes. The buffer's length is set to n, and the data pointer is
 * valid even if n is zero.
 *
 * @param n Number of bytes to allocate for the buffer. May be zero.
 *
 * @return Pointer to a newly allocated buffer_t on success, or NULL if
 *         memory allocation fails.
 *
 * @note Memory: Caller must free the returned buffer using buffer_free().
 */
Dependencies: None

FUNCTION IMPLEMENTATION:
```c
// C program for the function called buffer_new_with_size
// Contains target function implementation and dependency signatures

#include <string.h>
#include <stdio.h>
#include <stdarg.h>
#include <stdlib.h>
#include <ctype.h>
#include <sys/types.h>
#include "buffer.h"

// Target function implementation
buffer_t *
buffer_new_with_size(size_t n) {
  buffer_t *self = malloc(sizeof(buffer_t));
  if (!self) return NULL;
  self->len = n;
  self->data = self->alloc = calloc(n + 1, 1);
  return self;
}

